      "definition": "动画是一种用 @keyframes 定义多个阶段，并控制其播放方式的 CSS 动效 加载指示、分步入场等连续变化可用 animation；简单的悬停和选中反馈通常用 过渡 Transition 就够了。循环和大幅移动容易干扰阅读，必须尊重 prefers-reduced-motion；结束后是否停在最后一帧也应由实际界面状态决定。",
